import os, glob, re

# Load grids from session log
def load():
    import json
    d = os.environ['RLM_SESSION_DIR']
    session_name = os.path.basename(d)
    log_path = os.path.normpath(os.path.join(d, '..', '..', 'sessions', session_name + '.jsonl'))
    print(f"Loading from: {log_path}")
    try:
        with open(log_path, 'r') as f:
            lines = f.readlines()
    except FileNotFoundError:
        return {}

    G = {}
    for line in lines:
        msg = json.loads(line)
        role = msg.get('role', '')
        content = msg.get('content', '')

        # Look for demo pairs
        if 'Demo pair' in content:
            if 'input' in content.lower() or 'Output' in content:
                # Extract grid info
                match = re.search(r'Demo pair (\d+) (input|output)', content)
                if match:
                    idx = int(match.group(1))
                    grid_type = match.group(2)

                    # Find the actual grid text - it should be after the label
                    # The format shows: Demo pair 1 input (7x7):\n followed by grid rows
                    pattern = rf'Demo pair {idx} ({grid_type}) \([^)]+\):\s*\n((?:\d+\s*){grid_type})*\s*'
                    if grid_type == 'input':
                        rows = re.findall(r'^\d+\s+\d+\s+\d+\s+\d+\s+\d+\s+\d+\s+\d+\s+$', content, re.MULTILINE)
                    else:
                        rows = re.findall(r'^\d+\s+\d+\s+\d+\s+\d+\s+\d+\s+\d+\s+\d+\s+$', content, re.MULTILINE)

                    if grid_type == 'output' and rows:
                        G[idx-1] = [[int(x) for x in r.split()] for r in rows]
                        print(f"Loaded Demo pair {idx} output: {G[idx-1][:3]}")

    return G

