# BFS from all 0s with 8-connectivity
def bfs_distance_8(grid):
    rows = len(grid)
    cols = len(grid[0])
    dist = [[float('inf')] * cols for _ in range(rows)]
    queue = deque()

    # Start from all 0 positions and positions out of bounds
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                dist[r][c] = 0
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] != 0 and dist[nr][nc] == float('inf'):
                        dist[nr][nc] = dist[r][c] + 1
                        queue.append((nr, nc))

    return dist

