# Let me carefully implement the transform rule and test it on both demos
# Rule:
# 1. Find all 2x2 blocks of 8s
# 2. Find connected components (blocks that share any cell)
# 3. In each component:
#    - a) The topmost block (min row, then min col) → all cells become 1
#    - b) All other blocks → cells become mixed based on column position

def find_2x2_blocks(grid):
    N = len(grid)
    blocks = []
    for r in range(N - 1):
        for c in range(N - 1):
            if all(grid[r+dr][c+dc] == 8 for dr in [0, 1] for dc in [0, 1]):
                blocks.append((r, c))
    return blocks

def get_blocks_cells(blocks):
    """Get all cells covered by blocks"""
    cells = set()
    for (r, c) in blocks:
        for dr in [0, 1]:
            for dc in [0, 1]:
                cells.add((r + dr, c + dc))
    return cells

def find_connected_components(blocks):
    """Find connected components of blocks that share any cell"""
    used = set()
    components = []

    for b in sorted(blocks):
        if b not in used:
            # BFS to find all blocks that share cells with current block
            component = []
            stack = [b]
            while stack:
                curr = stack.pop()
                if curr in used:
                    continue
                used.add(curr)
                component.append(curr)

                curr_cells = {(curr[0], curr[1]), (curr[0], curr[0]+1), 
                             (curr[0]+1, curr[1]), (curr[0]+1, curr[0]+1)}

                for other in blocks:
                    if other not in used:
                        other_cells = {(other[0], other[1]), (other[0], other[0]+1),
                                     (other[0]+1, other[1]), (other[0]+1, other[0]+1)}
                        if curr_cells & other_cells:
                            stack.append(other)
            components.append(component)

    return components

def find_topmost_block(component):
    """Find the topmost block (min row, then min col)"""
    return min(component, key=lambda x: (x[0], x[1]))

def transform(grid):
    N = len(grid)
    result = [[0] * N for _ in range(N)]
    blocks = find_2x2_blocks(grid)

    if not blocks:
        return result

    components = find_connected_components(blocks)

    # For each component, assign values based on topmost block
    for component in components:
        topmost = find_topmost_block(component)

        # Topmost block gets all 1s
        r, c = topmost
        for dr in [0, 1]:
            for dc in [0, 1]:
                result[r + dr][c + dc] = 1

        # All OTHER cells in the component get mixed values based on col
        for (br, bc) in component:
            for dr in [0, 1]:
                for dc in [0, 1]:
                    r, c = br + dr, bc + dc
                    # Skip cells already set to 1
                    if result[r][c] == 1:
                        continue
                    # Mixed value based on column position
                    if c in [0, 1]:
                        result[r][c] = 3
                    elif c == 2:
                        result[r][c] = 2
                    else:  # c >= 3
                        result[r][c] = 4

    return result

