    elif col == 2:
        return 2
    else:
        return 4

def transform(grid):
    N = len(grid)
    M = len(grid[0]) if N > 0 else 0
    result = [[0] * M for _ in range(N)]

    blocks = find_2x2_blocks(grid)
    if not blocks:
        return result

    components = find_connected_components(blocks)

    for component in components:
        topmost = min(component, key=lambda x: (x[0], x[1]))

        # Topmost block gets all 1s
        tr, tc = topmost
        for dr in [0, 1]:
            for dc in [0, 1]:
                r, c = tr + dr, tc + dc
                if 0 <= r < N and 0 <= c < M:
                    result[r][c] = 1

        # Other blocks get column-based values
        for (br, bc) in component:
            if (br, bc) == topmost:
                continue
            for dr in [0, 1]:
                for dc in [0, 1]:
                    r, c = br + dr, bc + dc
                    if 0 <= r < N and 0 <= c < M and grid[r][c] == 8:
                        if result[r][c] == 0:
                            result[r][c] = get_val(c)

    return result

